#!/usr/bin/env python3
"""Write the versioned M3 supplement from M3-SUP-R2 numeric tables."""
import csv,json,math,sys
from pathlib import Path
REPO=Path(__file__).resolve().parents[1];ROOT=REPO/"reports/nns_vit_endpoint_m3_sup_r2_20260919";PAPER=REPO/"papers/nns_vit_endpoint"
def rows(name):
 with (ROOT/name).open() as f:return list(csv.DictReader(f))
def sci(x):return f"{float(x):.3e}"
def num(x,n=4):return f"{float(x):.{n}f}"
def ci(x,n=4):
 a=json.loads(x);return f"[{a[0]:.{n}f}, {a[1]:.{n}f}]"
def table(lines,header):return header+"\n"+"\n".join(lines)
def main():
 errors=rows("m3a_error_distribution.csv");operators=rows("operator_validation_table.csv");blocks=rows("block_summary.csv");cls=rows("cls_patch_summary.csv");cancel=rows("cancellation_summary.csv");fd=rows("finite_difference_diagnostics.csv");review=json.loads((ROOT/"cancellation_float64_review.json").read_text())
 error_lines=[]
 for model in ("fcn","cnn","cnn_maxpool","residual_mlp","residual_cnn"):
  for dtype in ("float32","float64"):
   p=next(r for r in errors if r["group"]=="model_dtype" and r["key"]==model+"|"+dtype and r["metric"]=="relative_l2");t=next(r for r in errors if r["group"]=="model_dtype" and r["key"]==model+"|"+dtype and r["metric"]=="max_tolerance_ratio");error_lines.append(f"| {model} | {dtype} | {p['n']} | {sci(p['median'])} | {sci(p['q99'])} | {sci(p['maximum'])} | {sci(t['maximum'])} |")
 error_table=table(error_lines,"| Network | Precision | Comparisons | Median relative L2 | 99% relative L2 | Max relative L2 | Max tolerance ratio |\n|---|---|---:|---:|---:|---:|---:|")
 op_lines=[f"| {r['operator']} | {r['directions']} | {r['dtype']} | {sci(r['max_analytic_autograd_jvp_relative_error'])} | {sci(r['max_jvp_vjp_identity_relative_error'])} | {sci(r['max_best_finite_difference_relative_error'])} | 9 | analytic + AD JVP/VJP + FD |" for r in operators]
 op_table=table(op_lines,"| Operator | Directions | Precision | Max analytic–AD JVP | Max JVP–VJP | Max best-step FD | Epsilons | Checks |\n|---|---:|---|---:|---:|---:|---:|---|")
 block_lines=[]
 for model in ("vit_b16","deit_s16"):
  for b in range(12):
   value={r["metric"]:r for r in blocks if r["model"]==model and int(r["block"])==b};block_lines.append(f"| {model} | {b} | {num(value['entropy']['median'])} {ci(value['entropy']['ci95'])} | {num(value['locality']['median'])} {ci(value['locality']['ci95'])} | {num(value['distance']['median'])} {ci(value['distance']['ci95'])} | {num(value['net_ratio']['median'],6)} {ci(value['net_ratio']['ci95'],6)} |")
 block_table=table(block_lines,"| Model | Block | Entropy [95% CI] | Locality [95% CI] | Distance [95% CI] | R_net [95% CI] |\n|---|---:|---:|---:|---:|---:|")
 cls_lines=[]
 for model in ("vit_b16","deit_s16"):
  for b in range(12):
   r=next(x for x in cls if x["model"]==model and x["stratum"]==f"block_{b:02d}");cls_lines.append(f"| {model} | {b} | {num(r['median_difference'])} | {ci(r['ci95'])} | {r['positive']}/{r['negative']}/{r['ties']} |")
 cls_table=table(cls_lines,"| Model | Block | Median CLS−patch entropy | 95% image-bootstrap CI | Positive/negative/tie images |\n|---|---:|---:|---:|---:|")
 cancel_lines=[]
 for model in ("vit_b16","deit_s16"):
  for b in (0,5,11):
   for token_type in ("cls","patch"):
    value={r["metric"]:r for r in cancel if r["model"]==model and int(r["block"])==b and r["token_type"]==token_type};cancel_lines.append(f"| {model} | {b} | {token_type} | {num(value['within_rgb_channels']['median'])} | {num(value['within_patch_after_rgb_sum']['median'])} | {num(value['across_patch_signed']['median'])} | {num(value['whole_image_cancellation']['median'])} | {num(value['net_ratio']['median'],6)} |")
 cancel_table=table(cancel_lines,"| Model | Block | Token | RGB-channel C | Within-patch C | Across-patch C | Whole-image C | R_net |\n|---|---:|---|---:|---:|---:|---:|---:|")
 worst=sorted(fd,key=lambda x:float(x["best_float32_tolerance_ratio"]),reverse=True)[:10]
 fd_lines=[f"| {r['task_id']} | {r['block']} | {r['token']} | {r['channel']} | {r['direction']} | {sci(r['absolute_analytic_magnitude_float64'])} | {num(r['best_float32_tolerance_ratio'],3)} @ {r['best_float32_epsilon']} | {sci(r['best_float64_tolerance_ratio'])} @ {r['best_float64_epsilon']} |" for r in worst]
 fd_table=table(fd_lines,"| Task | Block | Token | Channel | Direction | |JVP| float64 | Best float32 ratio/eps | Best float64 ratio/eps |\n|---|---:|---:|---:|---:|---:|---:|---:|")
 common=f"""## Numerical-equivalence distribution\n\nThe 5,000 comparisons are numerical validation cases, not independent statistical samples. The overall relative-L2 median was 1.088e-16, the 99th percentile was 1.602e-7, and the maximum was 2.427e-7. Float64 had median 5.194e-17 and maximum 4.769e-16; float32 had median 3.506e-8, 99th percentile 1.782e-7, and maximum 2.427e-7.\n\n{error_table}\n\n## Operator-level directional validation\n\nEach operator used eight float64 directions and nine central-difference step sizes `[1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 3e-6, 1e-6]`. The checks validate the tested operator implementations and directions; end-to-end hooks, registries, and structural cuts remain supported by their separate closure, parity, and negative-control evidence.\n\n{op_table}\n\n## Twelve-block spatial broadening\n\nEach image first contributes a median over its frozen units at a block; the table then reports the median and 10,000-replicate image-bootstrap interval across 100 images. Entropy rises mainly through early and middle blocks, locality decreases throughout depth, and normalized distance increases through block 11. Entropy is nearly saturated by blocks 8–10 and is not strictly monotone at the final block. The precise result is therefore **spatial broadening of local input dependence**, rather than attainment of a uniform global state or acquisition of global semantics.\n\n{block_table}\n\n## CLS–patch entropy by block\n\nWithin each image and block, the 32 sampled CLS channels and 15×32 sampled patch-token channels are separately reduced by the median before taking the paired difference. The CLS distribution is more entropic at every block in both models, while the gap shrinks sharply with depth: from 0.4752/0.4712 at block 0 to 0.0086/0.0238 at block 11 for ViT-B/16 and DeiT-S, respectively. This is construct-validity evidence for broader CLS input dependence, not a causal measure of information integration.\n\n{cls_table}\n\n## Cancellation across scales\n\nFor raw signed maps, let `A=sum_(c,h,w)|E|`, `B=sum_(h,w)|sum_c E|`, `P=sum_patch|sum_(c,h,w in patch)E|`, and `N=|sum E|`. The scale-specific cancellation ratios are `1-B/A`, `1-P/B`, `1-N/P`, and `1-N/A`; `R_net=N/A`. Their survival identity `(B/A)(P/B)(N/P)=N/A` held to 6.94e-18. The 120-map subset shows that most cancellation occurs after RGB aggregation within patches and, increasingly at deeper sampled blocks, across patches. Thus high absolute mass can coexist with a small net first-order directional derivative. On the same 24 targets, float32 and newly recomputed float64 cancellation metrics differed by at most {review['max_cancellation_metric_absolute_difference']:.3e}.\n\n{cancel_table}\n\n## Finite-difference diagnostics\n\nThe retained float32 failures comprise 36 of 57,600 conditions (0.0625%) across 10 tasks. All failures use the first frozen patch token and occur in blocks 7–11 (19 ViT-B/16, 17 DeiT-S conditions). Float32 absolute FD error increased as epsilon decreased over the tested range: its median was 4.26e-3 at 1e-2 and 5.83e-2 at 3e-4. For the same coordinates, float64 showed the expected decrease followed by round-off increase, with median absolute error reaching 2.05e-10 at 3e-4. All 36 float64 counterparts passed, with best tolerance ratios between 7.92e-7 and 3.14e-3. Because these are post-block token-channel targets, the data do not identify a unique LayerNorm, softmax, or other operator as the source.\n\n{fd_table}\n"""
 zh="# Endpoint M3 补充分析 R2\n\n> 本文档补充已封存 M3；不改变原 10 项 Holm 判定。下列表格均为 supplementary/descriptive，除原 M3 判定外不新增 confirmatory test。\n\n"+common.replace("## Numerical-equivalence distribution","## 数值等价误差分布").replace("## Operator-level directional validation","## 算子级方向验证").replace("## Twelve-block spatial broadening","## 12-block 空间扩展").replace("## CLS–patch entropy by block","## 分层 CLS–patch entropy").replace("## Cancellation across scales","## 多尺度 cancellation").replace("## Finite-difference diagnostics","## 有限差分诊断")
 en="# Endpoint M3 Supplement R2\n\n> This supplement extends the sealed M3 presentation without changing its ten Holm decisions. All new tables are supplementary/descriptive and introduce no new confirmatory test.\n\n"+common
 (REPO/"docs/endpoint_m3_supplement_r2_20260919.md").write_text(zh);(PAPER/"zh/endpoint_m3_supplement_r2.md").write_text(zh);(PAPER/"en/endpoint_m3_supplement_r2.md").write_text(en)
 evidence=f"""# Endpoint M3-SUP-R1 evidence matrix\n\n| Supplement | Primary artifacts | Status |\n|---|---|---|\n| NNS equivalence distributions | `m3a_error_distribution.csv`, source `m3a_fidelity.json` | PASS |\n| Operator-level validation table | `operator_validation_table.csv`, source `m3a_operator_validation.json` | PASS |\n| Twelve-block atlas trajectories | `block_image_values.csv`, `block_summary.csv` | SUPPLEMENTARY DESCRIPTIVE |\n| Layerwise CLS–patch comparison | `cls_patch_image_values.csv`, `cls_patch_summary.csv` | SUPPLEMENTARY DESCRIPTIVE |\n| Multi-scale cancellation | `cancellation_map_values.csv`, `cancellation_summary.csv` | SUPPLEMENTARY DESCRIPTIVE |\n| Float64 cancellation stability | `cancellation_float64_review.json`, 24 targets | PASS |\n| Float32 failure diagnosis | `finite_difference_diagnostics.csv`, all 36 retained failures | PASS FLOAT64 RECOVERY; FLOAT32 FAIL RETAINED |\n| Figures | `figure_manifest.json`, five PNG/PDF pairs | PASS |\n""";(PAPER/"notes/endpoint_m3_supplement_evidence_matrix_r1.md").write_text(evidence);print(json.dumps({"status":"PASS","documents":3,"operators":len(operators),"block_rows":len(block_lines),"cls_rows":len(cls_lines),"fd_rows":len(fd)}))
 old_evidence=PAPER/"notes/endpoint_m3_supplement_evidence_matrix_r1.md"
 new_evidence=PAPER/"notes/endpoint_m3_supplement_evidence_matrix_r2.md"
 new_evidence.write_text(old_evidence.read_text().replace("M3-SUP-R1","M3-SUP-R2"));old_evidence.unlink()
if __name__=="__main__":main()
